<!--
@component Modal dialog for advanced PNG export with live preview and dimension/resolution controls.

   Properties:
   - `plotElement` - reference to the SVG element to export.
   - `fileName` - file name for download (without extension).
   - `initialWidth` - initial width in cm (default: 8).
   - `initialRes` - initial resolution in DPI (default: 300).
   - `onclose` - callback when dialog is closed.
-->
<script>
   import { onDestroy } from 'svelte';
   import { downloadPNG } from './methods.js';

   let {
      plotElement,
      fileName = 'plot',
      initialWidth = 8,
      initialRes = 300,
      onclose
   } = $props();

   const resOptions = [100, 150, 300, 600];

   // The dialog intentionally takes a snapshot of its initial props when it opens.
   function getInitialValues() {
      const svgWidth = plotElement ? (plotElement.clientWidth || plotElement.getBoundingClientRect().width) : 1;
      const svgHeight = plotElement ? (plotElement.clientHeight || plotElement.getBoundingClientRect().height) : 1;
      const parsedInitialRes = Number(initialRes);

      return {
         svgWidth,
         svgHeight,
         aspectRatio: svgWidth / svgHeight,
         width: initialWidth,
         res: resOptions.includes(parsedInitialRes) ? parsedInitialRes : 300,
         name: typeof fileName === 'string' ? fileName : 'plot'
      };
   }

   const initialValues = getInitialValues();
   const svgWidth = initialValues.svgWidth;
   const svgHeight = initialValues.svgHeight;
   const aspectRatio = initialValues.aspectRatio;

   // editable state — height always derived from width to preserve aspect ratio
   let width = $state(initialValues.width);
   const height = $derived(Math.max(4, Math.min(20, Math.round(width / aspectRatio * 10) / 10)));
   let res = $state(initialValues.res);
   let name = $state(initialValues.name);
   const nameValid = $derived(name.trim().length > 0);
   let exportError = $state('');

   // preview container ref
   let previewContainer = $state(null);
   let dialogElement = $state(null);

   // max preview width in pixels
   const maxPreviewWidth = 400;
   const previewHeight = $derived(Math.round(maxPreviewWidth / aspectRatio));

   // clone SVG into preview container on mount
   $effect(() => {
      if (!previewContainer || !plotElement) return;

      // clear previous content
      previewContainer.innerHTML = '';

      // clone the SVG
      const clone = plotElement.cloneNode(true);

      clone.setAttribute('viewBox', `0 0 ${svgWidth} ${svgHeight}`);
      clone.setAttribute('preserveAspectRatio', 'xMidYMid meet');
      clone.style.width = '100%';
      clone.style.height = '100%';
      clone.style.position = 'static';

      // fixes duplicate clipPath IDs
      const clipPaths = clone.querySelectorAll('clipPath');
      clipPaths.forEach((cp) => {
         const oldId = cp.getAttribute('id');
         if (oldId) {
            const newId = 'preview_' + oldId;
            cp.setAttribute('id', newId);
            const refs = clone.querySelectorAll(`[clip-path="url(#${oldId})"]`);
            refs.forEach((ref) => ref.setAttribute('clip-path', `url(#${newId})`));
         }
      });

      previewContainer.appendChild(clone);
   });

   function handleWidthChange(e) {
      width = parseFloat(e.target.value);
   }

   let saving = $state(false);
   let activeExportCleanup = null;
   let destroyed = false;

   onDestroy(() => {
      destroyed = true;
      activeExportCleanup?.();
      if (dialogElement?.open) dialogElement.close();
   });

   $effect(() => {
      if (dialogElement && !dialogElement.open) {
         dialogElement.showModal();
         dialogElement.querySelector('#export-name')?.focus();
      }
   });

   function closeDialog() {
      if (dialogElement?.open) dialogElement.close();
      onclose();
   }

   function handleSave() {
      if (saving) return;

      exportError = '';

      const exportWidth = Number(width);
      const exportHeight = Number(height);
      const exportRes = Number(res);

      const hasValidSize = Number.isFinite(exportWidth) && exportWidth >= 1 && exportWidth <= 30 &&
         Number.isFinite(exportHeight) && exportHeight >= 1 && exportHeight <= 30;
      const hasValidResolution = Number.isFinite(exportRes) && exportRes >= 50 && exportRes <= 1200;

      if (!hasValidSize || !hasValidResolution) {
         exportError = 'Export size or resolution is invalid.';
         return;
      }

      if (!plotElement || !(plotElement instanceof SVGElement) || !plotElement.parentElement) {
         exportError = 'The plot is not available for export.';
         return;
      }

      const container = plotElement.parentElement;
      const origStyle = container.style.cssText;
      let observer = null;
      let fallbackTimer = null;
      let firstFrame = null;
      let secondFrame = null;
      let exportStarted = false;
      let restored = false;

      function restorePlot() {
         if (restored) return;
         restored = true;

         observer?.disconnect();
         if (fallbackTimer !== null) clearTimeout(fallbackTimer);
         if (firstFrame !== null) cancelAnimationFrame(firstFrame);
         if (secondFrame !== null) cancelAnimationFrame(secondFrame);

         container.style.cssText = origStyle;
         saving = false;

         if (activeExportCleanup === restorePlot) {
            activeExportCleanup = null;
         }
      }

      function failExport(error) {
         console.error('Failed to prepare the plot for PNG export.', error);
         exportError = 'PNG export could not be started.';
         restorePlot();
      }

      function finishExport() {
         restorePlot();
         if (!destroyed) closeDialog();
      }

      activeExportCleanup = restorePlot;
      saving = true;

      // scale reference width with export width so smaller plots get
      // a smaller scale category → relatively larger fonts and details
      // 4cm → 360px (small), 8cm → 520px (medium), 16cm → 840px (large), 20cm → 1000px (xlarge)
      const refWidth = Math.round(200 + exportWidth * 40);
      const refHeight = Math.round(refWidth / aspectRatio);

      function doExport() {
         if (exportStarted || restored) return;
         exportStarted = true;

         observer?.disconnect();
         if (fallbackTimer !== null) clearTimeout(fallbackTimer);

         try {
            firstFrame = requestAnimationFrame(() => {
               firstFrame = null;
               secondFrame = requestAnimationFrame(() => {
                  secondFrame = null;

                  try {
                     // The callback fires after downloadPNG has serialized the SVG,
                     // so the live container can be restored before image encoding finishes.
                     const result = downloadPNG(
                        plotElement,
                        name.trim(),
                        exportWidth,
                        exportHeight,
                        exportRes,
                        finishExport
                     );

                     if (result === null) {
                        failExport(new Error('downloadPNG rejected the export settings.'));
                     }
                  } catch (error) {
                     failExport(error);
                  }
               });
            });
         } catch (error) {
            failExport(error);
         }
      }

      try {
         // temporarily resize plot container to a fixed reference size (off-screen,
         // hidden behind the dialog backdrop) so Svelte recomputes the layout
         container.style.cssText = `position:fixed;left:-9999px;top:-9999px;width:${refWidth}px;height:${refHeight}px;overflow:hidden;`;

         // wait for ResizeObserver → Svelte bindings → derived recomputation → DOM update
         // fallback timeout in case container is already at the target size
         fallbackTimer = setTimeout(doExport, 500);
         observer = new ResizeObserver(doExport);
         observer.observe(plotElement);
      } catch (error) {
         failExport(error);
      }
   }

   function handleCancel(e) {
      e.preventDefault();
      if (!saving) closeDialog();
   }

   function handleDialogClick(e) {
      e.stopPropagation();
      if (saving) return;

      const bounds = e.currentTarget.getBoundingClientRect();
      const clickedOutside = e.clientX < bounds.left || e.clientX > bounds.right ||
         e.clientY < bounds.top || e.clientY > bounds.bottom;

      if (clickedOutside) closeDialog();
   }

   // Keep keyboard events from activating an enclosing custom modal's handlers.
   // Native dialog behavior still handles Escape; the explicit Tab order avoids
   // browser/OS differences in which form controls participate in navigation.
   function handleKeydown(e) {
      e.stopPropagation();

      if (e.key !== 'Tab' || !dialogElement) return;

      const resolutionInput = dialogElement.querySelector(
         'input[name="export-res"]:checked'
      ) ?? dialogElement.querySelector('input[name="export-res"]');

      const controls = [
         dialogElement.querySelector('#export-name'),
         dialogElement.querySelector('#export-width'),
         resolutionInput,
         ...dialogElement.querySelectorAll('.export-dialog-actions button:not(:disabled)')
      ].filter(Boolean);

      if (controls.length === 0) return;

      const currentIndex = controls.indexOf(document.activeElement);
      const nextIndex = currentIndex === -1
         ? (e.shiftKey ? controls.length - 1 : 0)
         : (currentIndex + (e.shiftKey ? -1 : 1) + controls.length) % controls.length;

      e.preventDefault();
      controls[nextIndex].focus();
   }
</script>

<!-- Native modal events provide backdrop closing and isolate an enclosing custom modal's keyboard handlers. -->
<!-- svelte-ignore a11y_no_noninteractive_element_interactions -->
<dialog
   class="export-dialog"
   aria-label="Export as PNG"
   bind:this={dialogElement}
   oncancel={handleCancel}
   onclick={handleDialogClick}
   onkeydown={handleKeydown}
>
      <div class="export-dialog-title">Export as PNG</div>

      <div class="export-dialog-body">
         <!-- Preview -->
         <div class="export-dialog-preview"
            style="width:{maxPreviewWidth}px;height:{previewHeight}px;"
            bind:this={previewContainer}
         ></div>

         <!-- Controls -->
         <div class="export-dialog-controls">
            <div class="export-dialog-control">
               <label for="export-name">File name:</label>
               <input id="export-name" class="export-dialog-name" class:invalid={!nameValid} type="text" bind:value={name} />
            </div>

            <div class="export-dialog-control">
               <label for="export-width">Size, cm: ({width} × {height})</label>
               <input id="export-width" type="range" min="4" max="20" step="1" value={width} oninput={handleWidthChange} />
            </div>

            <div class="export-dialog-res">
               <span class="export-dialog-res-label">Resolution, dpi:</span>
               <div class="export-dialog-res-options">
                  {#each resOptions as opt}
                     <label class="export-dialog-res-btn" class:selected={res === opt}>
                        <input type="radio" name="export-res" value={opt} bind:group={res} />
                        {opt}
                     </label>
                  {/each}
               </div>
            </div>

            {#if exportError}
               <p class="export-dialog-error" role="alert">{exportError}</p>
            {/if}
         </div>
      </div>

      <div class="export-dialog-actions">
         <button type="button" class="export-dialog-cancel" onclick={closeDialog} disabled={saving}>Cancel</button>
         <button type="button" class="export-dialog-save" onclick={handleSave} disabled={!nameValid || saving}>Save</button>
      </div>
</dialog>

<style>
   .export-dialog::backdrop {
      background: rgba(0, 0, 0, 0.4);
   }

   .export-dialog {
      box-sizing: border-box;
      background: #fefefe;
      border: none;
      border-radius: 0.5em;
      box-shadow: 0 4px 24px rgba(0, 0, 0, 0.25);
      padding: 1.25em;
      min-width: 440px;
      max-width: 90vw;
      margin: auto;
      font-family: Arial, Helvetica, sans-serif;
      color: #606060;
   }

   .export-dialog-title {
      font-size: 1.1em;
      font-weight: bold;
      margin-bottom: 1em;
      color: #303030;
   }

   .export-dialog-body {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 1em;
   }

   .export-dialog-preview {
      border: 1px solid #dadada;
      background: #fff;
      overflow: hidden;
      border-radius: 0.25em;
   }

   .export-dialog-controls {
      width: 100%;
      display: flex;
      flex-direction: column;
      gap: 0.5em;
   }

   .export-dialog-control {
      display: flex;
      align-items: center;
      gap: 0.5em;
   }

   .export-dialog-control label {
      min-width: 110px;
      font-size: 0.85em;
      white-space: nowrap;
   }

   .export-dialog-control input[type="range"] {
      flex: 1;
      accent-color: #443333;
   }

   .export-dialog-name {
      flex: 1;
      padding: 0.25em 0.4em;
      border: 1px solid #dadada;
      border-radius: 0.35em;
      font-size: 0.85em;
      color: #606060;
      background: #fafafa;
      outline: none;
   }

   .export-dialog-name:focus {
      border-color: #909090;
   }

   .export-dialog-name.invalid {
      border-color: crimson;
   }

   .export-dialog-res {
      display: flex;
      align-items: center;
      gap: 0.5em;
   }

   .export-dialog-res-label {
      min-width: 110px;
      font-size: 0.85em;
      white-space: nowrap;
   }

   .export-dialog-res-options {
      display: flex;
      gap: 0.25em;
   }

   .export-dialog-res-btn {
      box-sizing: border-box;
      color: #606060;
      border: none;
      box-shadow: none;
      background: #fafafa;
      border-radius: 0.35em;
      padding: 0.25em 0.5em;
      font-size: 0.85em;
      cursor: pointer;
      user-select: none;
   }

   .export-dialog-res-btn:hover {
      background: #dadada;
   }

   .export-dialog-res-btn.selected {
      background: #443333;
      color: #fafafa;
   }

   .export-dialog-res-btn input {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      clip-path: inset(50%);
      white-space: nowrap;
      border: 0;
   }

   .export-dialog-name:focus-visible,
   .export-dialog-control input[type="range"]:focus-visible,
   .export-dialog-actions button:focus-visible,
   .export-dialog-res-btn:focus-within {
      outline: 2px solid #999191;
      outline-offset: 2px;
   }

   .export-dialog-error {
      margin: 0;
      color: crimson;
      font-size: 0.85em;
   }

   .export-dialog-actions {
      display: flex;
      justify-content: flex-end;
      gap: 0.5em;
      margin-top: 1em;
   }

   .export-dialog-actions button {
      padding: 0.4em 1.2em;
      border-radius: 0.35em;
      border: none;
      cursor: pointer;
      font-size: 0.85em;
   }

   .export-dialog-cancel {
      background: #fafafa;
      color: #606060;
   }

   .export-dialog-cancel:hover {
      background: #dadada;
   }

   .export-dialog-save {
      background: #443333;
      color: #fafafa;
   }

   .export-dialog-save:hover {
      background: #665555;
      color: #fafafa;
   }

   .export-dialog-save:disabled {
      background: #dadada;
      color: #909090;
      cursor: default;
   }
</style>
