<script>
   /**************************************************************/
   /* AppContainer for applying                                  */
   /* -------------------------                                  */
   /* app container for applying preprocessing model to new data */
   /**************************************************************/


   import AppPlots from '@mdatools-apps/shared/components/prep/AppPlots.svelte';
   import ModelLoader from '@mdatools-apps/shared/components/prep/ModelLoader.svelte';
   import DataLoader from '../shared/DataLoader.svelte';
   import { getShortData, NROWS } from '@mdatools-apps/shared/methods/prep.js';

   // WASM promise and session object from parent app
   let {WASM, backupSession, session = $bindable()} = $props();

   // get part of the session for this tab
   const s = $derived(session['apply']);

   // the short sets are cut from the data and never stored: an effect wrote them into the
   // session, where nothing declared or checked them
   const rawdataShort = $derived(s.rawdata ? getShortData(s.rawdata, NROWS) : null);
   const prepdataShort = $derived(s.prepdata ? getShortData(s.prepdata, NROWS) : null);

   // effect to track changes in dataset and models
   $effect(() => {
      if (s.model === null) {
         s.rawdata = null;
         s.prepdata = null;
      }
   });

   $effect(() => {
      if (s.rawdata === null) {
         s.prepdata = null;
      }
   });


   // reactive effect for backing up the session. the session is read by 'backupSession' when the
   // write is due, not here, and the first run is skipped: it only ever coincides with a session
   // the app was given as a whole, which is already on disk, is written by 'MainApp' itself, or is
   // a fresh one that need not be stored. the values after the function are the dependencies (see
   // 'backupSession')
   let mounted = false;
   $effect(() => {
      const deps = [s.rawdata, s.prepdata, s.model];
      if (mounted) backupSession(() => session, ...deps);
      mounted = true;
   });

</script>

<div class="app-container">

   <!-- left column with main app controls -->
   <div class="app-controls">

      <div class="model-loader">
         <ModelLoader bind:model={s.model} />
      </div>

      {#if s.model}
      <div class="data-loader">
         <DataLoader {WASM} bind:rawdata={s.rawdata} bind:prepdata={s.prepdata} model={s.model} />
      </div>
      {/if}
   </div>

   <!-- right column with help text or with plots and plot controls -->
   <div class="app-content">
      {#if !s.rawdata}
         <div class="help-text">
            <p>
               In this tab you can apply preprocessing model, developed in <em>Create</em> tab to a new dataset.
            </p>
            {#if !s.model}
            <p><strong>Step 1.</strong></p>
            <p>Load JSON file with a model you saved from <em>Create</em> tab.</p>
            {:else}
            <p><strong>Step 2.</strong></p>
            <p>Load your data from single CSV file or single/multiple SPC files. See details about data file in the <em>Create</em> tab.</p>
            {/if}
         </div>
      {:else if rawdataShort && prepdataShort}
         <!-- the set is trimmed already, so the plots get no bounds -->
         {#key rawdataShort }
         <AppPlots
            rawdata={rawdataShort}
            prepdata={prepdataShort}
            left={-1}
            right={-1}
         />
         {/key}
      {/if}
   </div>
</div>

