<script>
   /**************************************************************/
   /* DataLoader for Preprocessing app                           */
   /* --------------------------------                           */
   /* Loads raw dataset from CSV or SPC file                     */
   /* if model is provided, applies it and returns 'prepdata'    */
   /**************************************************************/

   import { untrack } from 'svelte';
   import { FileSelector, Switch, Spinner, Select, Container, Button, TextInput } from 'svelte-controls-basic';
   import { downloadPrepData } from '../utils.js';
   import { applyPrep } from '@mdatools-apps/shared/methods/prep.js';
   import { parseCSV, parseCSVParams, readSPCFiles } from '@mdatools-apps/shared/utils';

   import DatasetWidget from '@mdatools-apps/shared/widgets/DatasetWidget.svelte';

   let {
      WASM = null,
      model = null,                     // preprocessing model
      rawdata = $bindable(null),        // JSON with loaded dataset
      prepdata = $bindable(null),       // JSON with preprocessed dataset
      title = 'Raw data',
   } = $props();

   // prefix for the label ids the controls below are named by. it must be unique on the page and
   // both tabs which mount this component stay mounted, so it can not be written out by hand
   const uid = $props.id();

   // possible delimiters and header options
   const sepOptions = [',', ';'];
   const headerOptions = ['no', 'labels', 'values'];

   // data properties
   let dataFile = $state();              // CSV or SPC file
   let varvaluesName = $state('');       // name of the variable values to be used as header
   let varvaluesUnits = $state('');      // units of the variable values
   let firstColumn = $state('data');     // what is located in the first column ('data', 'groups', 'response')

   // data properties, that will be autodetected from CSV file
   let sep = $state(',');                // separator between values
   let header = $state('no');            // first row contains header (labels or values)
   let hasLabels = $state(false);        // first column contains row labels
   let hasClassLabels = $state(false);   // if data file contains class labels

   // promise, app status for handling and showing errors
   let promise = $state(null);
   let status = $state('neutral');
   let errMsg = $state('');


   // method for showing error. it takes a string or an Error: the box printed the Error object,
   // which reads 'Error: ...'. the dataset is no longer dropped here: a failed apply nulled it,
   // the effect on a null 'rawdata' below then cleared the file, and the 'dataFile' effect reset
   // this message before it was shown
   function setError(msg) {
      status = 'error';
      errMsg = msg instanceof Error ? msg.message : String(msg);
      console.error(msg)
   }

   // method for setting neutral state. a step which succeeds sets it too: there used to be a
   // 'success' status as well, and nothing told the two apart
   function setNeutral() {
      status = 'neutral';
      errMsg = '';
   }

   // reset whole component to initial state of the component
   function reset () {
      // retires an apply in flight: the effect sees no data and starts none
      predictRun++;
      dataFile = '';
      rawdata = null;
      prepdata = null;
      varvaluesName = '';
      varvaluesUnits = '';
      // the block under a loaded set awaits the promise of the newest apply: one a reset retired,
      // still pending, put its spinner under a set the model refused before a new apply
      promise = null;
      setNeutral();
   }


   // every apply is stamped with the run which asked for it, and only the newest run may write;
   // a run is retired by a newer one, by 'reset' and by the component going away. the C call
   // itself blocks the page, so the window is the module instantiation, which yields: a reset
   // pressed in it nulled 'rawdata', and the run then read it and reported a TypeError. plain
   // 'let', never '$state' (see 'PrepWidget')
   let predictRun = 0;
   $effect(() => () => { predictRun++; });

   // method to apply preprocessing model
   function predict() {
      if (!rawdata || !model) return;

      const w = widthError(rawdata);
      if (w) {
         setError(w);
         return;
      }

      const myRun = ++predictRun;
      promise = WASM()
         .then(Module => {
            if (myRun !== predictRun) return;
            // the snapshot leaves the matrix out: it cloned it in full for 'applyPrep' to drop
            const { values, ...meta } = rawdata;
            prepdata = applyPrep(Module, { values, ...$state.snapshot(meta) }, model);
            setNeutral();
         })
         .catch(e =>{
            if (myRun !== predictRun) return;
            prepdata = null;
            setError(e);
         });
   };

   // a guess is read asynchronously and must not land after the file was changed, cleared or
   // loaded: every run of the 'dataFile' effect below takes the next number, and a read that
   // finishes with an older one is dropped
   let guessRun = 0;
   // the component going away retires a read in flight as well: an spc set landing after that
   // was written through the binding all the same
   $effect(() => () => { guessRun++; });

   // guess dataset parameters by reading first 100 kB of CSV file
   function guessParams(dataFile) {

      // no data file is provided - no guessing
      if (!dataFile || dataFile.size < 10) return;

      // read first 100Kb
      const chunkSize = 100000;
      const first100KB = dataFile.slice(0, chunkSize);
      const myRun = guessRun;

      const reader = new FileReader();
      reader.onload = () => {
         if (myRun !== guessRun) return;
         const csvString = reader.result;
         if (!csvString || csvString.length === 0) return;

         // 'parseCSVParams' throws when it can not make sense of the chunk: too few rows, no
         // delimiter it detects, or a value it can not read as a number. this runs inside a
         // FileReader callback, so an error thrown here escapes into the event loop instead of
         // any caller, and without the catch the component said nothing about why the guess
         // did not happen. the chunk can be the reason on its own: a file with very wide rows
         // has its last sampled row cut at the boundary, so the message names the chunk and
         // does not repeat the parser's sentence, which speaks of the whole file
         try {
            let fewRowsPerClass;
            [sep, hasLabels, hasClassLabels, header, , fewRowsPerClass] = parseCSVParams(csvString);
            // a group column in column 0 of three rows or fewer per value on average is replicate
            // row labels
            if (fewRowsPerClass) {
               hasLabels = true;
               hasClassLabels = false;
            }
            // from this file's guess alone: the groups of the last file must not take a column here
            firstColumn = hasClassLabels ? 'groups' : 'data';
         } catch (e) {
            console.error(e);
            setError('Could not guess the CSV parameters from the first 100 KB of the file. ' +
               'Check the delimiter, header and row label settings and try to load it.');
         }
      };

      reader.onerror = () => {
         if (myRun !== guessRun) return;
         // the handler's argument is a ProgressEvent, which used to be printed as '[object
         // ProgressEvent]'; the reason is on the reader
         const reason = reader.error ? reader.error.message : 'unknown error';
         setError('Error reading CSV file. ' + reason);
      };

      reader.readAsText(first100KB);
   }

   // the message for a set of the wrong width for the model, or '' when it fits or there is no
   // model. checked where a set is admitted, by both file paths - the SPC path loaded such a set
   // and left 'predict' to report it, with the set on screen - and in 'predict' for a stored
   // pair, which passes through neither
   function widthError(d) {
      const npred = d.values.ncols - d.nresp;
      return model && npred !== model.npred
         ? `Number of predictors in the dataset (${npred}) does not match the expected ` +
            `number (${model.npred}).`
         : '';
   }

   // Gets CSV file content as string and creates dataset object.
   function setData(strData) {
      try{
         const d = parseCSV(
            strData,
            sep,
            header,
            hasLabels,
            firstColumn === 'groups',              // hasClassNames
            varvaluesName,
            varvaluesUnits,
            firstColumn === 'response' ? 1 : 0     // nresp
         );
         if (d.values.nrows < 1 ) {
            throw new Error('Dataset must have at least 1 row.');
         }

         if (d.classNames.length > d.values.nrows / 2) {
            throw new Error('Dataset has too many unique class labels (' + d.classNames.length + '), check your CSV file.');
         }

         const w = widthError(d);
         if (w) throw new Error(w);

         d['fileName'] = dataFile.name.replace(/\.[^/.]+$/, "");
         rawdata = d;
         setNeutral();
      } catch (e) {
         setError(e);
      }
   }

   // a file is a csv when its name says so. the browser fills 'type' from extension mappings of
   // its own or of the platform, and firefox up to esr 140 takes the platform's for '.csv',
   // where any installed application may have registered the extension under a type of its
   // choosing; the selector next to this already accepts files by their extension. an Array
   // and the empty string have no 'name'
   const isCSVFile = f =>
      !!f && typeof f.name === 'string' && f.name.toLowerCase().endsWith('.csv');

   // a read in progress: the selector and the settings give way to a spinner until the data
   // lands or the read fails, and both of those set the status again
   function setLoading() {
      status = 'loading';
      errMsg = '';
   }

   // promise for reading the CSV file
   function readCSV () {
      setLoading();
      // a guess still in flight is retired: it would land during the read and write the
      // delimiter, or the status, over it
      guessRun++;
      const reader = new FileReader();
      reader.onload = () => { setData(reader.result) };
      // without this a file which can not be read would leave the spinner up for good
      reader.onerror = () => {
         const reason = reader.error ? reader.error.message : 'unknown error';
         setError('Error reading CSV file. ' + reason);
      };
      reader.readAsText(dataFile);
   }

   // promise for reading the SPC file. the read is retired like a guess, by the next run of the
   // 'dataFile' effect and by the teardown of 'guessRun': its set used to land after the file
   // had been changed or cleared, or after the component had gone
   async function readSPC () {
      setLoading();
      const myRun = guessRun;
      try {
         // several files arrive as a plain Array, from the dialog and from a drop alike since
         // svelte-controls-basic 3.2.0; only a single File has to be wrapped
         const dataFiles = Array.isArray(dataFile) ? dataFile : [dataFile];
         const d = await readSPCFiles(dataFiles);
         if (myRun !== guessRun) return;
         const w = widthError(d);
         if (w) {
            setError(w);
            return;
         }
         rawdata = d;
         setNeutral();
      } catch (e) {
         if (myRun !== guessRun) return;
         setError('Failed to read SPC file: ' + (e instanceof Error ? e.message : String(e)));
      }
   }

   // if data file is selected - guess parameters
   $effect(() => {
      guessRun++;

      if (dataFile === undefined) return;

      // if data file is empty reset status and error messages. untracked: 'reset' writes the bound
      // props through the parent's setter, which reads the tab's session, so the effect subscribed
      // to the session and ran again, with the file still '', on a session imported over a tab
      // holding no data, and nulled the data the import brought
      if (dataFile === null || dataFile === '') {
         untrack(reset);
         return;
      }

      // dataFile holds several files: a plain Array, from the dialog and from a drop alike
      if (Array.isArray(dataFile)) {

         // 'v' is a File: 'v.slice()' is Blob.slice and returns a Blob, never the extension, so
         // the name has to be taken explicitly. the selector accepts '.SPC' as well
         if (!dataFile.every(v => v.name.toLowerCase().endsWith('.spc'))) {
            setError('Multiple file selection is allowed only for SPC files.');
            return;
         }

         readSPC();
         return;
      }

      if (isCSVFile(dataFile)) {
         guessParams(dataFile);
         setNeutral();
         return;
      }

      readSPC();
   });

   // a change of the delimiter drops the message of the last parse
   $effect(() => {
      void sep;
      setNeutral();
   });

   // a dataset and a model with no preprocessed set and no message: a new apply. the bound
   // fields are seeded 0 by the session, which a test against null let through to 'predict',
   // and 'model' is null in the create tab, which never applies
   $effect(() => {
      if (rawdata && model && !prepdata && errMsg === '') {
         predict();
      }
   });

   $effect(() => {
      if (rawdata === null || rawdata === 0) dataFile = '';
   });
</script>

{#if status === 'loading'}

   <!-- the file is read asynchronously, so the spinner is in the DOM before the parse, which
        runs on the main thread. whether a frame is painted in between is the browser's call -->
   <Container>
      <Spinner />
      <p>Loading data...</p>
   </Container>

{:else if !rawdata }

   <!-- show if data is not loaded -->
   <Container>
      <FileSelector
         message="Select CSV or SPC file with dataset"
         acceptType=".csv, .spc"
         multiple={true}
         bind:file={dataFile}
      />
   </Container>

   <!-- show if file is selected but data is not loaded -->
   {#if isCSVFile(dataFile)}
   <Container label="Delimiter" id="{uid}-sep">
      <Select bind:value={sep} options={sepOptions} />
   </Container>
   <Container label="Row labels" id="{uid}-haslabels">
      <Switch bind:value={hasLabels} options={['no', 'yes']} />
   </Container>
   <Container label="First column" id="{uid}-firstcolumn">
      <Select bind:value={firstColumn} options={['data', 'groups', 'response']} />
   </Container>
   <Container label="Header" id="{uid}-header">
      <Select bind:value={header} options={headerOptions} />
   </Container>
   {#if header==='values'}
   <Container label="Header name" id="{uid}-varvaluesname">
      <TextInput bind:value={varvaluesName} placeholder="e.g. Wavelength" />
   </Container>
   <Container label="Header units" id="{uid}-varvaluesunits">
      <TextInput bind:value={varvaluesUnits} maxLength={10} placeholder="e.g. nm" />
   </Container>
   {/if}
   <Container label="&nbsp;">
      <Button text='Load' onclick={readCSV}/>
   </Container>
   {/if}

{:else}


   {#if promise}

      <!-- calculation is in process. 'predict' ends in a catch of its own which reports through
           'setError', so the promise never rejects and a catch block here would never show -->
      {#await promise}
         <Container>
            <Spinner />
            <p>Loading data...</p>
         </Container>
      {/await}

   {/if}

{/if}

{#if rawdata }
   <!-- dataset is loaded - show info and cancel button -->
   <DatasetWidget dataset={rawdata} {reset} {title} />
{/if}
{#if prepdata && model}
   <Container label="Download">
      <Button text="Preprocessed data" onclick={() => downloadPrepData(prepdata)}/>
   </Container>
{/if}

<!-- error message -->
{#if status === 'error'}
<Container status="error">
   <p>{errMsg}</p>
</Container>
{/if}

